# Let's manually identify patterns by examining differences
inputs = ['cvu', 'fvgkuu', 'wfyg', 'fkvvg', 'bwiaef']
outputs = ['xfvu', 'fvkgkguu', 'yfykg', 'fkgvvkg', 'byiaef']

print("Detailed analysis:")
for i, (inp, out) in enumerate(zip(inputs, outputs)):
    print(f"\nPair {i}: '{inp}' -> '{out}'")

    # Find where they differ
    min_len = min(len(inp), len(out))
    diff_pos = -1
    for j in range(min_len):
        if inp[j] != out[j]:
            diff_pos = j
            break

    if diff_pos == -1:
        if len(inp) != len(out):
            diff_pos = min_len
        else:
            print("  No difference found")
            continue

    print(f"  First difference at position {diff_pos}")

    # Show what changes
    if diff_pos < len(inp) and diff_pos < len(out):
        print(f"  Character at pos {diff_pos}: '{inp[diff_pos]}' -> '{out[diff_pos]}'")
    elif diff_pos < len(inp):
        print(f"  Character at pos {diff_pos}: '{inp[diff_pos]}' -> (removed)")
    elif diff_pos < len(out):
        print(f"  Character at pos {diff_pos}: (added) -> '{out[diff_pos]}'")

